import { createSchedule } from '@/api/schedule';
import { useAISolver } from '@/composables/useAISolver';
import type { SolverPayload } from '@/api/solver';

const solver = useAISolver();

async function handleGenerate() {
  // 1. 전월 데이터 검증
  const validation = validateLastMonthData(
    grid.employees.value,
    grid.dates.value,
    grid.assignments.value
  );

  if (!validation.isValid) {
    message.error('전월 데이터를 모두 입력해주세요');
    dialog.error({
      title: '전월 데이터 미입력',
      content: validation.errors.join('\n'),
      positiveText: '확인',
    });
    return;
  }

  // 2. schedules 레코드 생성
  try {
    const schedule = await createSchedule(
      scheduleStore.basicInfo!.organizationId,
      scheduleStore.basicInfo!.month
    );

    // 3. AI Solver 호출
    const lastMonthDates = grid.dates.value.filter(d => d.isLastMonth);
    const thisMonthDates = grid.dates.value.filter(d => !d.isLastMonth);

    const lastMonthAssignments: any = {};
    const thisMonthAssignments: any = {};

    grid.employees.value.forEach(emp => {
      lastMonthAssignments[emp.id] = {};
      thisMonthAssignments[emp.id] = {};

      lastMonthDates.forEach(d => {
        if (grid.assignments.value[emp.id]?.[d.date]) {
          lastMonthAssignments[emp.id][d.date] = grid.assignments.value[emp.id][d.date];
        }
      });

      thisMonthDates.forEach(d => {
        if (grid.assignments.value[emp.id]?.[d.date]) {
          thisMonthAssignments[emp.id][d.date] = grid.assignments.value[emp.id][d.date];
        }
      });
    });

    const payload: SolverPayload = {
      scheduleId: schedule.id,
      employees: grid.employees.value,
      requirements: scheduleStore.siteRequirements,
      lastMonthAssignments,
      thisMonthAssignments,
    };

    await solver.startSolver(schedule.id, payload);

    // 4. Step 4로 이동
    scheduleStore.nextStep();
    router.push(`/schedule/step4/${schedule.id}`);

    // LocalStorage 삭제
    if (STORAGE_KEY.value) {
      localStorage.removeItem(STORAGE_KEY.value);
    }
  } catch (error: any) {
    message.error('근무표 생성 실패: ' + error.message);
  }
}
```

